-- PDCA GE SISTÊMICO (auditor_pdca_2, 2026-11-08) · RD-98 pilar 3 (origem do dado) + classificação de system_screens
-- Preenche views_consumidas/rpcs_chamadas das telas GE SEM origem (derivado do CÓDIGO: supabase.rpc('fn_*') e .from('tabela')
-- varrendo a rota e os componentes/libs que ela importa), classifica 'modulo' das nulas pela rota e marca 'pronto'
-- SÓ as 2 jornadas que o auditor PROVOU (renegociacao, precificacao). Sem mudança de backend/cálculo/RLS/dado de cliente.
-- Aditivo/idempotente: views/rpcs via UNION (nunca remove o que já existia); modulo via COALESCE (só preenche nulo).
-- system_screens é metadata de SISTEMA (catálogo de telas), não dado de cliente. Code: code-desenvolvedor-3

UPDATE public.system_screens SET rpcs_chamadas = ARRAY(SELECT DISTINCT unnest(COALESCE(rpcs_chamadas,'{}'::text[]) || ARRAY['fn_ajuda_campo_listar','fn_ajuda_campo_uso','fn_cliente_buscar','fn_cliente_criar_inline','fn_contrato_solicitar','fn_fornecedor_contato_salvar','fn_municipio_por_nome_uf','fn_registrar_evento_auth','fn_registrar_travamento']::text[]) ORDER BY 1), views_consumidas = ARRAY(SELECT DISTINCT unnest(COALESCE(views_consumidas,'{}'::text[]) || ARRAY['agency_clientes','agency_proposta_itens','agency_propostas','erp_cliente_arquivos','erp_clientes','erp_contratos_arquivos','erp_fornecedor_contatos','erp_gov_nfse_municipios','erp_lancamentos']::text[]) ORDER BY 1), modulo = COALESCE(modulo, 'cadastros'), atualizado_em = now() WHERE rota = '/dashboard/cadastros/clientes';
