-- Prova RD-38 (roda na aplicação): nenhuma tela GE auditável deve ficar sem origem do dado,
-- exceto as 4 rotas de redirect (compras, estoque, conciliacao, conciliacao/lote) que não têm dado próprio.
DO $$
DECLARE v_sem int;
BEGIN
  SELECT count(*) INTO v_sem FROM public.system_screens
  WHERE estado_real <> 'removido'
    AND (rota LIKE '/dashboard/financeiro%' OR rota LIKE '/dashboard/comercial%' OR rota LIKE '/dashboard/fiscal%'
      OR rota LIKE '/dashboard/compras%' OR rota LIKE '/dashboard/cadastros%' OR rota LIKE '/dashboard/estoque%'
      OR rota LIKE '/dashboard/pdv%' OR rota LIKE '/dashboard/gestao-empresarial%')
    AND coalesce(array_length(views_consumidas,1),0)=0 AND coalesce(array_length(rpcs_chamadas,1),0)=0
    AND rota NOT IN ('/dashboard/compras','/dashboard/estoque','/dashboard/financeiro/conciliacao','/dashboard/financeiro/conciliacao/lote');
  IF v_sem <> 0 THEN
    RAISE EXCEPTION 'PDCA GE sistêmico: % telas GE ainda sem origem do dado (esperado 0, fora os 4 redirects)', v_sem;
  END IF;
END $$;
